    n = length(array)
    swapped = True

    while (swapped):
        swapped = False

        // Left to Right
        for (i = 0; i < n - 1; i += 1):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap(array[i], array[i + 1])
                swapped = True
            end if
        end for

        // Right to Left
        for (i = n - 1; i > 0; i -= 1):
            @mark<i, outline, yellow> if (array[i] < array[i - 1]):
                @mark<i, highlight, green> swap(array[i], array[i - 1])
                swapped = True
            end if
        end for

        n -= 1
    end while

    return array
end fun

