// Define the Bubble Sort function
fun Bubble_Sort(@init<table> array):
    n = length(array)
    for (i = 0; i < n; i += 1):
        for (j = 0; j < n - i - 1; j += 1):
            @mark<j, outline, yellow> if (array[j] > array[j + 1]):
                @mark<j, highlight, green> swap(array[j], array[j + 1])
            end if
        end for
    end for
    return array
end fun

// Define the Binary Search function
fun Binary_Search(@init<table> collection, target, size): 
    low = 0
    high = size - 1

    while (low <= high):
        // Calculate middle index
        mid = floor((low + high) / 2)

        // Get value at the middle
        @mark<mid, highlight, yellow> val = collection[mid]

        if (val == target):
            @mark<mid, highlight, green> return mid
        end if

        if (val < target):
            @mark<low, outline, yellow> low = mid + 1
        end if

        if (val > target):
            @mark<high, outline, yellow> high = mid - 1
        end if
    end while

    @log<warn, "Not found"> return -1
end fun

// Call the Binary Search function
result = Binary_Search(a1, 4, size(a1))

