fun Cocktail_Shaker_Sort(@init<table> array):
    n = length(array)
    swapped = True

    while (swapped):
        swapped = False

        // Left to Right pass
        for (i = 0; i < n - 1; i += 1):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap(array[i], array[i + 1])
                swapped = True
            end if
        end for

        if (not(swapped)):
            break
        end if

        swapped = False

        // Right to Left pass
        for (i = n - 1; i > 0; i -= 1):
            @mark<i, outline, yellow> if (array[i] < array[i - 1]):
                @mark<i, highlight, green> swap(array[i], array[i - 1])
                swapped = True
            end if
        end for
    end while

    return array
end fun

result = Cocktail_Shaker_Sort(a1)

