        while (true):
            i += 1
            @mark<i, outline, yellow> if (array[i] % 2 == 0):
                break
            end if
        end while

        // Move right pointer backward until an even number is found
        while (true):
            j -= 1
            @mark<j, outline, yellow> if (array[j] % 2 != 0):
                break
            end if
        end while

        // If pointers cross/meet, then the partition op is completed.
        if (i >= j):
            @log<info, "Partition complete"> return array
        end if

        // Swap elements at i and j if in the wrong partition
        @mark<i, highlight, green> swap(array[i], array[j])

    end while
end fun

