a1 = arr[0, 1, 0, 3, 12]

fun Move_ZerosToEnd(@init<table> array):
    n = length(array)
    zeroCount = 0

    // Count the number of zeros in the array
    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> if (array[i] == 0):
            zeroCount += 1
        end if
    end for

    // Move non-zero elements to the beginning
    j = 0
    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> if (array[i] != 0):
            @mark<j, highlight, green> swap(array[i], array[j])
            j += 1
        end if
    end for

    // Fill the rest of the array with zeros
    for (i = n - zeroCount; i < n; i += 1):
        @mark<i, outline, yellow> array[i] = 0
    end for

    return array
end fun

result = Move_ZerosToEnd(a1)

