fun Remove_Duplicates(@init<table> array):
    n = length(array)

    if (n == 0):
        @log<warn, "Array is empty, nothing to remove."> return 0
    end if

    @mark<0, outline, yellow> count = 1

    for @mark<i, outline, yellow> (i = 1; i < n; i += 1):
        if (array[i] != array[count - 1]):
            @mark<count, highlight, green> array[count] = array[i]
            @mark<count, outline, yellow> count += 1
        end if
    end for

    // Resize array to new count
    @mark<count, outline, yellow> new_array = arr[count]
    for @mark<i, outline, yellow> (i = 0; i < count; i += 1):
        @mark<i, highlight, green> new_array[i] = array[i]
    end for

    return count
end fun

