fun Shell_Sort(@init<table> array):
    n = length(array)

    gap = floor(n / 2)

    while (gap > 0):
        for (i = gap; i < n; i += 1):
            temp = array[i]
            j = i

            while (j >= gap and array[j - gap] > temp):
                @mark<j, outline, yellow> array[j] = array[j - gap]
                j -= gap
            end while

            @mark<j, highlight, green> array[j] = temp
        end for

        gap = floor(gap / 2)
    end while

    return array
end fun

