        end if

        // Move the appropriate pointer
        if (sum < target):
            @mark<left, outline, yellow> left += 1
        else:
            @mark<right, outline, yellow> right -= 1
        end if
    end while

    // If no pair is found
    @log<warn, "No pair found"> return arr[-1] and arr[-1]
end fun

