// Shell Sort

a1 = arr[5, 1, 4, 2, 8]

fun Shell_Sort(@init<table> array):
    n = length(array)

    // Start with a big gap, then reduce the gap
    for (gap = floor(n / 2); gap > 0; gap = floor(gap / 2)):

        // Do a gapped insertion sort for this gap size.
        // The first gap elements array[0..gap-1] are already in gapped order
        // keep adding one more element until the entire array is gap sorted
        for (i = gap; i < n; i += 1):

            // add array[i] to the elements that have been gap sorted
            // save array[i] in temp and make a hole at position i
            @mark<i, outline, yellow> temp = array[i]
            @mark<i, highlight, green> j = i

            // shift earlier gap-sorted elements up until the correct location for array[i] is found
            while (j >= gap and array[j - gap] > temp):
                @mark<j, outline, yellow> array[j] = array[j - gap]
                @mark<j, highlight, green> j = j - gap

            // put temp (the original array[i]) in its correct location
            @mark<i, outline, yellow> array[j] = temp
        end while
    end for

    return array
endfun()

